<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue'
const props=defineProps<{page:string}>()
type Fact={id:string;field:string;entity_type:string;normalized_value:unknown;raw_value:string|null;raw_excerpt:string;locator:string;source_url:string;published_at:string|null;collected_at:string;version_label:string;version_id:string;verification_status:string;snapshot_id:string;sha256:string}
type Entity={id:string;name?:string;ordinal?:number;boss_count?:number|null;item_name?:string;boss_name?:string;snapshot_id:string;facts:Fact[];hp?:number|null;attack?:number|null;defense?:number|null;description?:string}
const detail=ref<any>(null),stages=ref<Entity[]>([]),bosses=ref<Entity[]>([]),rewards=ref<Entity[]>([]),sources=ref<any[]>([]),conflicts=ref<any[]>([]),stats=ref<any>({})
const error=ref(''),loading=ref(true),selected=ref(''),query=ref('')
const labels:Record<string,string>={name:'副本名称',minimum_level:'准入等级',minimum_battle_power:'战斗力要求',pet_requirement:'三宠要求',open_channels:'开放版本 / 渠道',entry_location:'副本入口',entry_coordinates:'入口坐标',entry_map:'入口地图',open_hours:'开放时间',team_limit:'队伍人数限制',boss_total:'BOSS 总数',final_boss:'最终 BOSS',time_bypass_item:'时间限制豁免物品',time_bypass_acquisition:'豁免物品获得方式',game_build_number:'游戏构建版本号',launch_release_date:'副本首次开放日期',map_walkability:'可通行地图 / 障碍',map_dimensions:'地图尺寸',trap_mechanics:'机关机制',boss_combat_mechanics:'BOSS 战斗机制',monster_attributes:'怪物数值属性',consumables:'入场消耗',daily_entry_limit:'每日进入次数',reward_probabilities:'掉落概率',boss_stage_order:'BOSS 阶段顺序',official_illustration_urls:'官方图示链接',hp:'生命',attack:'攻击',defense:'防御',skills:'技能'}
const title=computed(()=>props.page==='#/flow'?'九星副本流程':props.page==='#/sources'?'数据来源管理':'九星副本知识库')
const snapshots=computed(()=>sources.value.flatMap(s=>s.snapshots.map((p:any)=>({...p,url:s.url,url_date_hint:s.url_date_hint}))))
const facts=computed<Fact[]>(()=>detail.value?.facts.filter((f:Fact)=>!selected.value||f.snapshot_id===selected.value)||[])
const filteredStages=computed(()=>stages.value.filter(s=>s.snapshot_id===selected.value).sort((a,b)=>(a.ordinal||0)-(b.ordinal||0)))
const filteredBosses=computed(()=>bosses.value.filter(b=>b.snapshot_id===selected.value))
const filteredRewards=computed(()=>rewards.value.filter(r=>r.snapshot_id===selected.value&&(!query.value||((r.item_name||'')+(r.boss_name||'')).includes(query.value))))
const unknowns=computed(()=>detail.value?.unknowns.filter((f:Fact)=>f.snapshot_id===selected.value)||[])
function value(v:unknown){return v===null||v===undefined?'UNKNOWN':Array.isArray(v)?v.join('、'):typeof v==='object'?JSON.stringify(v):String(v)}
function factOf(entity:Entity){return entity.facts.find(f=>f.verification_status!=='UNKNOWN')}
function sourceName(id:string){const s=snapshots.value.find(s=>s.id===id);return s?s.url.includes('2015-10-18')?'2015 历史页':s.url.includes('2010-06-02')?'2010 URL 日期线索页':'官网指南（无发布日期）':id.slice(0,8)}
async function load(){loading.value=true;error.value='';try{const fetchJSON=async(path:string)=>{const r=await fetch('/api/knowledge/'+path);if(!r.ok)throw new Error(path+' HTTP '+r.status);return r.json()};const [list,ss,cc]=await Promise.all([fetchJSON('dungeons'),fetchJSON('sources'),fetchJSON('conflicts')]);stats.value=list.stats;sources.value=ss.items;conflicts.value=cc.items;if(list.items.length){const [d,s,b,r]=await Promise.all(['dungeons/alama','dungeons/alama/stages','dungeons/alama/bosses','dungeons/alama/rewards'].map(fetchJSON));detail.value=d;stages.value=s.items;bosses.value=b.items;rewards.value=r.items;selected.value=snapshots.value[0]?.id||''}}catch(e){error.value=String(e)}finally{loading.value=false}}
onMounted(load)
watch(()=>props.page,()=>{query.value='';error.value=''})
</script>
<template>
<div class="shell">
<aside><div class="logo">M<span> / </span>A</div><h3>魔域智能 Agent</h3><small>KNOWLEDGE LAB · V1.1</small><nav><a href="/#/observations">◎ 场景观察中心</a><a href="/#/console">◈ 运行控制台</a><a href="/#/knowledge" :class="{active:page==='#/knowledge'}">◇ 九星副本知识库</a><a href="/#/flow" :class="{active:page==='#/flow'}">⇢ 九星副本流程</a><a href="/#/sources" :class="{active:page==='#/sources'}">▤ 数据来源管理</a></nav><div class="aside-note"><b>OFFICIAL_WEB</b><p>公开网页证据<br>当前官服未验证<br>只读知识查询</p></div></aside>
<main><header><div><div class="eyebrow">TRACEABLE OFFICIAL KNOWLEDGE</div><h1>{{title}}</h1><p>阿拉玛的哭泣 · 保留原始值、版本差异与未知字段</p></div><button @click="load">刷新知识数据</button></header>
<div class="notice">OFFICIAL_WEB 官网公开资料 · 网页证据已提取，当前官服尚未验证。知识库阶段仅供查阅，不能转换为自动执行指令。</div>
<div class="metrics"><article><label>官网来源 / 快照</label><strong>{{stats.sources??0}} <i>/ {{stats.snapshots??0}}</i></strong><small>原始 HTML + SHA-256</small></article><article><label>有网页证据的事实</label><strong>{{stats.official_page_facts??0}}</strong><small>按字段与快照计数，含重复历史事实</small></article><article><label>当前官服已验证事实</label><strong>{{stats.current_game_verified_facts??0}}</strong><small>暂无 GAME_OBSERVATION 验证</small></article><article><label>冲突 / 未发现字段</label><strong>{{stats.conflicts??0}} <i>/ {{stats.unknown_fields??0}}</i></strong><small>保留差异，不自动覆盖</small></article></div>
<p v-if="loading" class="empty">正在查询真实数据库资料…</p><p v-if="error" class="error">{{error}}</p><p v-if="!loading&&!detail&&!error" class="empty">尚未采集官网资料，请运行 scripts/collect_official.py</p>
<template v-if="detail && page!=='#/sources'"><div class="version-select"><label>查看来源版本 / 快照</label><select v-model="selected"><option v-for="s in snapshots" :key="s.id" :value="s.id">{{sourceName(s.id)}} · 抓取 {{new Date(s.fetched_at).toLocaleString()}} · {{s.sha256.slice(0,10)}}</option></select><small>发布日期缺失时显示 UNKNOWN；URL 中的日期仅作为线索。</small></div></template>
<template v-if="detail && page==='#/knowledge'">
<section class="panel"><div class="panel-title"><h2>副本基础资料</h2><span>历史公开资料 · 非当前配置</span></div><div class="knowledge-facts"><article v-for="f in facts.filter(f=>!f.field.startsWith('stage_'))" :key="f.id"><div class="fact-label">{{labels[f.field]||f.field}} <span :class="['evidence-tag',f.verification_status==='UNKNOWN'?'unknown':'official']">{{f.verification_status==='UNKNOWN'?'尚未确认':'官方网页证据'}}</span></div><div class="fact-value">{{value(f.normalized_value)}}</div><details class="evidence"><summary>来源与原始证据</summary><p><a :href="f.source_url" target="_blank" rel="noopener">{{f.source_url}}</a></p><p>发布时间 {{f.published_at??'UNKNOWN'}} · 抓取 {{new Date(f.collected_at).toLocaleString()}}</p><p>{{f.version_label}}</p><p>原始值：{{f.raw_value??'NULL'}}；未检测到字段不代表官网永远未公开。</p><blockquote>{{f.raw_excerpt||'正文中未检测到该字段；不推测数值。'}}</blockquote><code>{{f.locator}}</code><p>SHA-256 {{f.sha256}}</p><a :href="'/api/knowledge/snapshots/'+f.snapshot_id">下载原始 HTML 快照</a></details></article></div></section>
<section class="panel history"><div class="panel-title"><h2>BOSS 与怪物属性</h2><span>未公开数值不使用模拟器属性补全</span></div><div class="boss-grid"><article v-for="boss in filteredBosses" :key="boss.id"><h3>{{boss.name}}</h3><p>生命 {{value(boss.hp)}} · 攻击 {{value(boss.attack)}} · 防御 {{value(boss.defense)}}</p><p>{{boss.facts.find(f=>f.field==='description')?.normalized_value}}</p><a v-if="factOf(boss)" :href="factOf(boss)!.source_url" target="_blank" rel="noopener">官网档案依据 ↗</a><span class="evidence-tag official">官方网页证据 · 非游戏实测</span></article></div></section>
<section class="panel history"><div class="panel-title"><h2>掉落物品与奖励种类</h2><input v-model="query" placeholder="搜索碎片、晶石或幻兽"></div><div class="table-wrap"><table><thead><tr><th>BOSS</th><th>官网列出的物品</th><th>单次数量</th><th>掉落概率</th><th>来源</th></tr></thead><tbody><tr v-for="reward in filteredRewards" :key="reward.id"><td>{{reward.boss_name}}</td><td>{{reward.item_name}}</td><td>UNKNOWN</td><td>UNKNOWN</td><td><a :href="factOf(reward)?.source_url" target="_blank" rel="noopener">官网原文 ↗</a></td></tr></tbody></table></div></section>
<section class="panel history"><div class="panel-title"><h2>机关与特殊机制</h2><span>公开文本直接提取</span></div><div class="mechanic-list"><article v-for="m in detail.mechanics.filter((m:Entity)=>m.snapshot_id===selected)" :key="m.id"><b>{{m.name}}</b><p>{{m.description}}</p><span class="evidence-tag official">官网网页证据</span><a :href="factOf(m)?.source_url" target="_blank" rel="noopener"> 查看来源</a></article><p>地图网格、机关触发条件、首领战斗机制及入场消耗：UNKNOWN。原图链接仅作为官网图示，未声称可用于寻路。</p></div></section>
</template>
<template v-if="detail && page==='#/flow'"><section class="panel"><div class="panel-title"><h2>官网阶段流程 · 只读参考</h2><span>依据正文表格编号</span></div><div class="flow-list"><article><div class="step-number">入</div><div><h3>进入卡利亚堡</h3><p>{{value(facts.find(f=>f.field==='entry_coordinates')?.normalized_value)}} · {{value(facts.find(f=>f.field==='minimum_level')?.normalized_value)}} 级</p><span class="evidence-tag official">官方网页证据</span><p>坐标和准入条件必须按来源查看；当前官服状态未确认。</p></div></article><article v-for="s in filteredStages" :key="s.id"><div class="step-number">{{s.ordinal}}</div><div><h3>{{s.name}}</h3><p>本阶段首领数量：{{value(s.boss_count)}}</p><span class="evidence-tag official">官方网页证据</span> <span class="evidence-tag unknown">移动路线 / 技能时序尚未确认</span><p>原表头：{{s.facts.find(f=>f.field==='name')?.raw_value}}</p><a :href="factOf(s)?.source_url" target="_blank" rel="noopener">来源 ↗</a></div></article></div></section><section class="panel history"><div class="panel-title"><h2>证据边界</h2></div><div class="boundary-grid"><article><span class="evidence-tag official">已有官方证据</span><p>入口条件、表格阶段编号、首领名称、掉落物品名称。</p></article><article><span class="evidence-tag observed">GAME_OBSERVATION</span><p>当前有 {{detail.observations.length}} 条游戏观察。观察模式尚未启用，不展示虚构的实测机制。</p></article><article><span class="evidence-tag unknown">尚未确认</span><p>可通行地图、怪物属性、技能周期、机关触发与当前版本有效性。</p></article><article><span class="evidence-tag simulated">SIMULATOR</span><p>V1.0 的四阶段原创地图、75/50 HP、25 攻击及模拟金币均独立于本官网流程。</p><a href="/#/observations">◎ 场景观察中心</a><a href="/#/console">打开本地模拟器控制台</a></article></div></section></template>
<template v-if="page==='#/sources'"><section class="panel"><div class="panel-title"><h2>官方页面与采集快照</h2><span>采集通过本地 CLI 执行</span></div><div class="source-list"><article v-for="source in sources" :key="source.id"><h3><a :href="source.url" target="_blank" rel="noopener">{{source.url}}</a></h3><p>来源 {{source.source_type}} · 最近结果 {{source.last_status}} · 发布 {{source.published_at??'UNKNOWN'}} · URL 日期线索 {{source.url_date_hint??'NULL'}}</p><p>最近抓取 {{source.last_fetched_at?new Date(source.last_fetched_at).toLocaleString():'UNKNOWN'}} · 请求尝试 {{source.fetch_count}}</p><p v-if="source.last_error" class="error">{{source.last_error}}</p><div v-for="snap in source.snapshots" :key="snap.id" class="snapshot"><b>HTTP {{snap.http_status}} · {{snap.encoding}} · 事实 {{snap.fact_count}} / UNKNOWN {{snap.unknown_count}}</b><p>首次采集 {{new Date(snap.fetched_at).toLocaleString()}} · 最后复见 {{new Date(snap.last_seen_at).toLocaleString()}}</p><code>SHA-256 {{snap.sha256}}</code><p>{{snap.version_label}}</p><a :href="'/api/knowledge/snapshots/'+snap.id">下载原始 HTML</a></div><details><summary>采集成功 / 失败记录</summary><p v-for="attempt in source.attempts" :key="attempt.id">{{attempt.attempted_at}} · {{attempt.status}} · HTTP {{attempt.http_status??'NULL'}} · {{attempt.error}}</p></details></article></div></section><section class="panel history"><div class="panel-title"><h2>冲突记录 · 不自动覆盖</h2><span>{{conflicts.length}} 项待人工复核</span></div><div class="conflict-list"><article v-for="conflict in conflicts" :key="conflict.id"><h3>{{labels[conflict.field]||conflict.field}} <span class="evidence-tag unknown">{{conflict.status}}</span></h3><p>{{conflict.explanation}}</p><div v-for="f in conflict.evidence" :key="f.id"><b>{{sourceName(f.snapshot_id)}}：</b>{{value(f.normalized_value)}} <a :href="f.source_url" target="_blank" rel="noopener">来源</a></div></article></div></section><section class="panel history"><div class="panel-title"><h2>待补全信息</h2><span>不会使用模拟数据补全</span></div><div class="mechanic-list"><p>游戏实际构建版本、副本首次开放日期、详细地图、怪物生命/攻击/防御/技能、机关触发、战斗机制、单次掉落数量与概率、每日次数和入场消耗。</p><p>部分页面未公开发布时间或战斗力要求，保留 NULL / UNKNOWN；当前官服所有事实有效性仍待授权观察验证。</p></div></section></template>
<footer>运行环境 SIMULATOR · 正式版公开资料 OFFICIAL_WEB · OBSERVATION 暂未启用</footer>
</main></div>
</template>
